#!/usr/bin/env node
"use strict";

/**
 * refresh-skill-index.js — regenerate Skills/index.md + Skills/index.json
 * from the frontmatter of every curated skill (Skills/*.md, excluding Community/ and _drafts/).
 * Generated files; never hand-edit. Spec: Projects/Skill & Tool Router — Design Spec.md §8.
 */

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const DEFAULT_SKILLS = path.join(ROOT, "Skills");

function parseArgs(argv) {
  const args = { dir: DEFAULT_SKILLS, out: DEFAULT_SKILLS };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--dir") args.dir = path.resolve(argv[++i] || ".");
    else if (argv[i] === "--out") args.out = path.resolve(argv[++i] || ".");
  }
  return args;
}

function parseFrontmatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return { data: {}, body: text };
  const data = {};
  for (const line of m[1].split("\n")) {
    const idx = line.indexOf(":");
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    let val = line.slice(idx + 1).trim();
    if (!key) continue;
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) val = val.slice(1, -1);
    if (val.startsWith("[") && val.endsWith("]")) val = val.slice(1, -1).split(",").map(s => s.trim()).filter(Boolean);
    else if (val === "true") val = true;
    else if (val === "false") val = false;
    else if (/^-?\d+(\.\d+)?$/.test(val)) val = Number(val);
    data[key] = val;
  }
  return { data, body: m[0] };
}

function slug(name) {
  return String(name).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

function listSkillFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter(f => f.endsWith(".md") && f !== "index.md")
    .map(f => path.join(dir, f));
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const files = listSkillFiles(args.dir);
  const REQUIRED = ["description", "triggers", "quality", "status"];
  const skills = [];
  const errors = [];

  for (const file of files) {
    const raw = fs.readFileSync(file, "utf8");
    const { data } = parseFrontmatter(raw);
    if (data.status === "deprecated") continue;
    const missing = REQUIRED.filter(k => data[k] === undefined || data[k] === null || data[k] === "" || (Array.isArray(data[k]) && data[k].length === 0));
    if (missing.length > 0) {
      errors.push(path.basename(file) + ": missing " + missing.join(", "));
      continue;
    }
    skills.push({
      id: data.id || slug(data.skill_name),
      skill_name: data.skill_name || path.basename(file, ".md"),
      role: data.role || "",
      description: data.description,
      triggers: Array.isArray(data.triggers) ? data.triggers : [data.triggers],
      depends_on: Array.isArray(data.depends_on) ? data.depends_on : [],
      uses_tools: Array.isArray(data.uses_tools) ? data.uses_tools : [],
      quality: Number(data.quality) || 0,
      status: data.status || "active",
      file: path.basename(file),
    });
  }

  if (errors.length > 0) {
    for (const e of errors) console.error("❌ " + e);
    process.exit(1);
  }

  skills.sort((a, b) => a.id.localeCompare(b.id));

  const dupWarnings = [];
  for (let i = 0; i < skills.length; i++) {
    for (let j = i + 1; j < skills.length; j++) {
      const a = new Set(skills[i].description.toLowerCase().split(/\W+/).filter(Boolean));
      const b = new Set(skills[j].description.toLowerCase().split(/\W+/).filter(Boolean));
      const inter = [...a].filter(x => b.has(x)).length;
      const union = new Set([...a, ...b]).size;
      if (union && inter / union > 0.7) dupWarnings.push(skills[i].skill_name + " ~ " + skills[j].skill_name);
    }
  }
  for (const w of dupWarnings) console.warn("⚠️  near-duplicate: " + w);

  const json = JSON.stringify(skills, null, 2) + "\n";
  fs.writeFileSync(path.join(args.out, "index.json"), json);

  let md = "# 🦸 AI-Suplex Skill Index\n\n";
  md += "> Generated by Tools/refresh-skill-index.js — do not hand-edit.\n\n";
  md += "> " + skills.length + " curated skills · " + new Date().toISOString().slice(0, 10) + "\n\n";
  md += "| Skill | Role | Triggers | Uses tools | Quality |\n|---|---|---|---|---|\n";
  for (const s of skills) {
    md += "| " + s.skill_name + " | " + s.role + " | " + s.triggers.join(", ") + " | " + (s.uses_tools.join(", ") || "—") + " | " + s.quality + " |\n";
  }
  fs.writeFileSync(path.join(args.out, "index.md"), md);

  console.log("Indexed " + skills.length + " skills → Skills/index.json + index.md");
  if (dupWarnings.length) console.log(dupWarnings.length + " near-duplicate warning(s)");
}

main();
